CREATE OR REPLACE FUNCTION public.invalidate_pick8_entry_sync()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'UPDATE' and row(new.matchday_id, new.submitted_at, new.total_goals_prediction)
    is not distinct from row(old.matchday_id, old.submitted_at, old.total_goals_prediction) then return new; end if;
  if tg_op <> 'INSERT' then perform public.invalidate_pick8_sync(old.matchday_id); end if;
  if tg_op = 'INSERT' or (tg_op = 'UPDATE' and new.matchday_id is distinct from old.matchday_id) then
    perform public.invalidate_pick8_sync(new.matchday_id);
  end if;
  return coalesce(new, old);
end;
$function$
CREATE OR REPLACE FUNCTION public.invalidate_pick8_fixture_sync()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'UPDATE' and
    (to_jsonb(new) - array['updated_at', 'created_at', 'last_synced_at']) is not distinct from
    (to_jsonb(old) - array['updated_at', 'created_at', 'last_synced_at']) then return new; end if;
  if tg_op <> 'INSERT' then perform public.invalidate_pick8_sync(old.matchday_id); end if;
  if tg_op = 'INSERT' or (tg_op = 'UPDATE' and new.matchday_id is distinct from old.matchday_id) then
    perform public.invalidate_pick8_sync(new.matchday_id);
  end if;
  return coalesce(new, old);
end;
$function$
CREATE OR REPLACE FUNCTION public.invalidate_pick8_selection_sync()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'UPDATE' and row(new.entry_id, new.fixture_id, new.category, new.selected_team_side)
    is not distinct from row(old.entry_id, old.fixture_id, old.category, old.selected_team_side) then return new; end if;
  if tg_op <> 'INSERT' then
    perform public.invalidate_pick8_sync(matchday_id) from public.entries where id = old.entry_id;
  end if;
  if tg_op = 'INSERT' or (tg_op = 'UPDATE' and new.entry_id is distinct from old.entry_id) then
    perform public.invalidate_pick8_sync(matchday_id) from public.entries where id = new.entry_id;
  end if;
  return coalesce(new, old);
end;
$function$
CREATE OR REPLACE FUNCTION public.invalidate_pick8_sync(check_matchday_id uuid)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  update public.matchdays set sync_pending = true, scoring_pending = true,
    sync_revision = sync_revision + 1, scoring_revision = scoring_revision + 1
  where id = check_matchday_id;
$function$
CREATE OR REPLACE FUNCTION public.prevent_provider_fixture_duplicates()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if exists (
    select 1 from public.matchdays
    where matchdays.id = new.matchday_id
      and matchdays.fixture_sync_mode = 'provider'
  ) and exists (
    select 1 from public.fixtures
    where fixtures.matchday_id = new.matchday_id
      and fixtures.id <> new.id
      and lower(btrim(fixtures.home_team_name)) = lower(btrim(new.home_team_name))
      and lower(btrim(fixtures.away_team_name)) = lower(btrim(new.away_team_name))
  ) then
    raise exception 'Provider matchdays cannot contain duplicate logical fixtures';
  end if;
  return new;
end;
$function$
CREATE OR REPLACE FUNCTION public.protect_entry_system_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  matchday_lock timestamptz;
begin
  if auth.role() = 'service_role' or public.is_pick8_admin() then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.user_id <> auth.uid() then
      raise exception 'Entry user must match the authenticated user';
    end if;
    if new.locked_at is not null or new.calculated_score is not null
      or new.score_calculated_at is not null then
      raise exception 'Players cannot set entry lock or scoring fields';
    end if;
  else
    if new.user_id is distinct from old.user_id
      or new.matchday_id is distinct from old.matchday_id
      or new.locked_at is distinct from old.locked_at
      or new.calculated_score is distinct from old.calculated_score
      or new.score_calculated_at is distinct from old.score_calculated_at then
      raise exception 'Players cannot change entry ownership, lock, or scoring fields';
    end if;
    if old.submitted_at is not null and new.submitted_at is null then
      raise exception 'Submitted entries cannot be changed back to drafts';
    end if;
    select locks_at into matchday_lock
    from public.matchdays where id = old.matchday_id;
    if matchday_lock is not null and now() >= matchday_lock
      and (
        new.total_goals_prediction is distinct from old.total_goals_prediction
        or new.submitted_at is distinct from old.submitted_at
      ) then
      raise exception 'Submission and Total Goals are locked at the first kickoff';
    end if;
  end if;
  return new;
end;
$function$
CREATE OR REPLACE FUNCTION public.protect_manual_matchday_from_provider_fixtures()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.last_synced_at is not null and exists (
    select 1
    from public.matchdays
    where matchdays.id = new.matchday_id
      and matchdays.fixture_sync_mode = 'manual'
  ) then
    raise exception 'Provider-synced fixtures cannot be written to a manual matchday';
  end if;
  return new;
end;
$function$
CREATE OR REPLACE FUNCTION public.protect_matchday_fixture_sync_mode()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.fixture_sync_mode is not distinct from old.fixture_sync_mode then
    return new;
  end if;
  if not (auth.role() = 'service_role' or public.is_pick8_admin()) then
    raise exception 'Only administrators can change fixture sync mode';
  end if;
  if old.status in ('locked', 'scoring', 'completed')
    or exists (
      select 1 from public.fixtures
      where fixtures.matchday_id = old.id
        and fixtures.kickoff_at <= now()
    )
    or exists (
      select 1 from public.entries
      where entries.matchday_id = old.id
        and (
          entries.submitted_at is not null
          or entries.calculated_score is not null
        )
    )
  then
    raise exception 'Fixture sync mode cannot change after kickoff, submission, or scoring';
  end if;
  if new.fixture_sync_mode = 'provider' and exists (
    select 1
    from public.fixtures first_fixture
    join public.fixtures duplicate_fixture
      on duplicate_fixture.matchday_id = first_fixture.matchday_id
     and duplicate_fixture.id > first_fixture.id
     and lower(btrim(duplicate_fixture.home_team_name)) = lower(btrim(first_fixture.home_team_name))
     and lower(btrim(duplicate_fixture.away_team_name)) = lower(btrim(first_fixture.away_team_name))
    where first_fixture.matchday_id = old.id
  ) then
    raise exception 'Duplicate logical fixtures must be resolved before enabling provider sync';
  end if;
  return new;
end;
$function$
CREATE OR REPLACE FUNCTION public.protect_pick8_sync_metadata()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if coalesce(auth.role(), '') not in ('', 'service_role') and pg_trigger_depth() = 1 then
    if tg_table_name = 'matchdays' then
      if tg_op = 'INSERT' then
        if new.applied_fixture_fingerprint is not null or new.last_upstream_check_at is not null or new.sync_pending or new.scoring_pending or new.sync_revision <> 0 or new.scoring_revision <> 0 then
          raise exception 'Sync metadata is server-managed';
        end if;
      elsif row(new.applied_fixture_fingerprint, new.last_upstream_check_at, new.sync_pending, new.scoring_pending, new.sync_revision, new.scoring_revision)
        is distinct from row(old.applied_fixture_fingerprint, old.last_upstream_check_at, old.sync_pending, old.scoring_pending, old.sync_revision, old.scoring_revision) then
        raise exception 'Sync metadata is server-managed';
      end if;
    else
      if tg_op = 'INSERT' then
        if not new.competition_refresh_pending or new.competition_revision <> 0 or new.competition_refresh_after is not null then raise exception 'Sync metadata is server-managed'; end if;
      elsif row(new.competition_refresh_pending, new.competition_revision, new.competition_refresh_after)
        is distinct from row(old.competition_refresh_pending, old.competition_revision, old.competition_refresh_after) then
        raise exception 'Sync metadata is server-managed';
      end if;
    end if;
  end if;
  return new;
end;
$function$
CREATE OR REPLACE FUNCTION public.protect_selection_scoring_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if auth.role() = 'service_role' or public.is_pick8_admin() then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.points_awarded is not null or new.is_correct is not null then
      raise exception 'Players cannot set selection scoring fields';
    end if;
  elsif new.entry_id is distinct from old.entry_id
    or new.points_awarded is distinct from old.points_awarded
    or new.is_correct is distinct from old.is_correct
  then
    raise exception 'Players cannot change selection ownership or scoring fields';
  end if;

  return new;
end;
$function$
CREATE OR REPLACE FUNCTION public.protect_submitted_entry_selections()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if auth.role() = 'service_role' or public.is_pick8_admin() then
    return old;
  end if;
  if exists (
    select 1 from public.entries
    where entries.id = old.entry_id
      and entries.submitted_at is not null
  ) then
    raise exception 'Submitted selections must be replaced, not deleted';
  end if;
  return old;
end;
$function$
CREATE OR REPLACE FUNCTION public.refresh_pick8_matchday_deadline(check_matchday_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  first_kickoff timestamptz;
begin
  select min(fixtures.kickoff_at)
  into first_kickoff
  from public.fixtures
  where fixtures.matchday_id = check_matchday_id;

  update public.matchdays
  set locks_at = first_kickoff,
      updated_at = case
        when locks_at is distinct from first_kickoff then now()
        else updated_at
      end
  where id = check_matchday_id
    and locks_at is distinct from first_kickoff;
end;
$function$
CREATE OR REPLACE FUNCTION public.require_complete_entry_submission()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  fixture_selection_count integer;
  fixture_category_count integer;
begin
  if new.submitted_at is null then
    return new;
  end if;

  select count(*), count(distinct category)
  into fixture_selection_count, fixture_category_count
  from public.entry_selections
  where entry_id = new.id
    and category in (
      'home_win',
      'away_win',
      'draw',
      'team_win',
      'team_lose',
      'team_score',
      'clean_sheet'
    );

  if new.total_goals_prediction is null
    or fixture_selection_count <> 7
    or fixture_category_count <> 7
  then
    raise exception using
      errcode = '23514',
      message = 'Entry must have all seven fixture selections and Total Goals before submission';
  end if;

  return new;
end;
$function$
CREATE OR REPLACE FUNCTION public.require_valid_submitted_entry_selections()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target_entry_id uuid;
  selection_count integer;
  category_count integer;
begin
  target_entry_id := case when tg_op = 'DELETE' then old.entry_id else new.entry_id end;

  if not exists (
    select 1 from public.entries
    where entries.id = target_entry_id
      and entries.submitted_at is not null
  ) then
    return null;
  end if;

  select count(*), count(distinct category)
  into selection_count, category_count
  from public.entry_selections
  where entry_id = target_entry_id;

  if selection_count <> 7 or category_count <> 7 then
    raise exception using
      errcode = '23514',
      message = 'Submitted entry selections must contain each Pick8 category exactly once';
  end if;

  return null;
end;
$function$
CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  new.updated_at := now();
  return new;
end;
$function$
CREATE OR REPLACE FUNCTION public.sync_pick8_matchday_deadline_from_fixtures()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'DELETE' then
    perform public.refresh_pick8_matchday_deadline(old.matchday_id);
    return old;
  end if;

  perform public.refresh_pick8_matchday_deadline(new.matchday_id);
  if tg_op = 'UPDATE' and old.matchday_id is distinct from new.matchday_id then
    perform public.refresh_pick8_matchday_deadline(old.matchday_id);
  end if;
  return new;
end;
$function$
CREATE OR REPLACE FUNCTION public.track_pick8_matchday_lifecycle()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'UPDATE' then
    if row(new.season_id, new.matchday_number, new.fixture_sync_mode, new.is_accelerated_test, new.status, new.opens_at, new.locks_at)
      is not distinct from row(old.season_id, old.matchday_number, old.fixture_sync_mode, old.is_accelerated_test, old.status, old.opens_at, old.locks_at) then return new; end if;
    new.sync_pending := true;
    new.sync_revision := old.sync_revision + 1;
    -- Status is also a scoring output. Do not invalidate the scorer's own
    -- input revision when it writes that output.
    if row(new.season_id, new.matchday_number, new.fixture_sync_mode, new.is_accelerated_test, new.opens_at, new.locks_at)
      is distinct from row(old.season_id, old.matchday_number, old.fixture_sync_mode, old.is_accelerated_test, old.opens_at, old.locks_at) then
      new.scoring_pending := true;
      new.scoring_revision := old.scoring_revision + 1;
    end if;
  end if;
  if tg_op <> 'INSERT' then
    update public.seasons set competition_refresh_pending = true, competition_revision = competition_revision + 1 where id = old.season_id;
  end if;
  if tg_op = 'INSERT' or (tg_op = 'UPDATE' and new.season_id is distinct from old.season_id) then
    update public.seasons set competition_refresh_pending = true, competition_revision = competition_revision + 1 where id = new.season_id;
  end if;
  return coalesce(new, old);
end;
$function$
CREATE OR REPLACE FUNCTION public.validate_entry_selection_matchday()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  entry_matchday_id uuid;
  fixture_matchday_id uuid;
begin
  select matchday_id
  into entry_matchday_id
  from public.entries
  where id = new.entry_id;

  select matchday_id
  into fixture_matchday_id
  from public.fixtures
  where id = new.fixture_id;

  if entry_matchday_id is null
    or fixture_matchday_id is null
    or entry_matchday_id <> fixture_matchday_id
  then
    raise exception 'Selection fixture must belong to the entry matchday';
  end if;

  return new;
end;
$function$
CREATE OR REPLACE FUNCTION public.validate_pick8_submission()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
    v_selection_count integer;
begin
    -- Only validate when an entry is being submitted.
    -- Draft entries may remain incomplete.
    if new.submitted_at is not null
       and old.submitted_at is null then

        select count(*)
        into v_selection_count
        from public.entry_selections
        where entry_id = new.id;

        if v_selection_count <> 7 then
            raise exception
                'Entry must contain all 7 fixture selections before submission. Current count: %.',
                v_selection_count;
        end if;

        if new.total_goals_prediction is null then
            raise exception
                'Entry must include a Total Goals prediction before submission.';
        end if;

    end if;

    return new;
end;
$function$
